import hashlib
import hmac
import json
import base64
import unicodedata
import time
import os

_jwt_secret = os.environ.get('JWT_SECRET')
if not _jwt_secret:
    raise RuntimeError('JWT_SECRET environment variable must be set to a strong secret')
SECRET_KEY = _jwt_secret.encode()

ALLOWED_ALGORITHMS = ['hs256', 'hs384', 'hs512']

def base64url_decode(data: str) -> bytes:
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def base64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def normalize_algorithm_name(alg: str) -> str:
    """Normalize algorithm name for consistent lookup.
    Uses NFKC normalization to handle equivalent representations."""
    return unicodedata.normalize('NFKC', alg).lower().strip()

def compute_hmac_signature(signing_input: str, secret: bytes, algorithm: str) -> str:
    """Compute HMAC signature for the given algorithm."""
    norm_alg = normalize_algorithm_name(algorithm)
    if norm_alg == 'hs256':
        sig = hmac.new(secret, signing_input.encode(), hashlib.sha256).digest()
        return base64url_encode(sig)
    elif norm_alg == 'hs384':
        sig = hmac.new(secret, signing_input.encode(), hashlib.sha384).digest()
        return base64url_encode(sig)
    elif norm_alg == 'hs512':
        sig = hmac.new(secret, signing_input.encode(), hashlib.sha512).digest()
        return base64url_encode(sig)
    return ''

def verify_token(token: str) -> dict:
    """Verify and decode a JWT token.

    Security: Only allows explicitly allowlisted algorithms.
    Uses constant-time comparison for signature verification.
    """
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Invalid token format: expected 3 parts')

    header_b64, payload_b64, signature_b64 = parts

    try:
        header = json.loads(base64url_decode(header_b64))
    except (json.JSONDecodeError, Exception) as e:
        raise ValueError(f'Invalid header: {e}')

    if not isinstance(header, dict) or 'alg' not in header:
        raise ValueError('Missing algorithm in header')

    raw_algorithm = header['alg']

    # Normalize BEFORE checking - allowlist approach
    algorithm = normalize_algorithm_name(raw_algorithm)

    # Security: only allow explicitly permitted algorithms
    if algorithm not in ALLOWED_ALGORITHMS:
        raise ValueError(f'Algorithm not allowed: {raw_algorithm}')

    # Verify signature based on normalized algorithm
    signing_input = f'{header_b64}.{payload_b64}'

    expected_sig = compute_hmac_signature(signing_input, SECRET_KEY, algorithm)
    if not expected_sig:
        raise ValueError(f'Failed to compute signature for: {raw_algorithm}')
    if not hmac.compare_digest(expected_sig, signature_b64):
        raise ValueError('Invalid signature')

    try:
        payload = json.loads(base64url_decode(payload_b64))
    except (json.JSONDecodeError, Exception) as e:
        raise ValueError(f'Invalid payload: {e}')

    if not isinstance(payload, dict):
        raise ValueError('Payload must be a JSON object')

    # Check expiration
    if 'exp' in payload:
        exp = payload['exp']
        if not isinstance(exp, (int, float)) or isinstance(exp, bool):
            raise ValueError('Invalid expiration claim')
        if time.time() > exp:
            raise ValueError('Token expired')

    return payload

def create_token(payload: dict, algorithm: str = 'HS256') -> str:
    """Create a signed JWT token."""
    norm_alg = normalize_algorithm_name(algorithm)
    if norm_alg not in ALLOWED_ALGORITHMS:
        raise ValueError(f'Algorithm not allowed: {algorithm}')

    header = {'alg': algorithm, 'typ': 'JWT'}
    header_b64 = base64url_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = base64url_encode(json.dumps(payload, separators=(',', ':')).encode())

    signing_input = f'{header_b64}.{payload_b64}'
    signature = compute_hmac_signature(signing_input, SECRET_KEY, algorithm)

    if not signature:
        raise ValueError(f'Failed to sign with algorithm: {algorithm}')

    return f'{signing_input}.{signature}'

def get_user_permissions(token: str) -> dict:
    """Extract user permissions from a verified token."""
    payload = verify_token(token)
    return {
        'user_id': payload.get('sub'),
        'roles': payload.get('roles', []),
        'permissions': payload.get('perms', []),
        'issued_at': payload.get('iat'),
        'expires_at': payload.get('exp')
    }
